    source: Source | IgnoredInput,
    ...defaults: Defaults
  ): Defu<Source, Defaults>;
  fn: DefuFn;
  arrayFn: DefuFn;
  extend(merger?: Merger): DefuFn;
}

export type MergeArrays<Destination, Source> =
  Destination extends Array<infer DestinationType>
    ? Source extends Array<infer SourceType>
      ? Array<DestinationType | SourceType>
      : Source | Array<DestinationType>
    : Source | Destination;

export type Merge<Destination extends Input, Defaults extends Input> =
  // Remove explicitly null types
  Destination extends nullish
    ? Defaults extends nullish
      ? nullish
      : Defaults
    : Defaults extends nullish
      ? Destination
      : // Handle arrays
        Destination extends Array<any>
        ? Defaults extends Array<any>
          ? MergeArrays<Destination, Defaults>
          : Destination | Defaults
        : // Don't attempt to merge Functions, RegExps, Promises
          // eslint-disable-next-line @typescript-eslint/ban-types
          Destination extends Function
          ? Destination | Defaults
          : Destination extends RegExp
            ? Destination | Defaults
            : Destination extends Promise<any>
              ? Destination | Defaults
              : // Don't attempt to merge Functions, RegExps, Promises
                // eslint-disable-next-line @typescript-eslint/ban-types
                Defaults extends Function
                ? Destination | Defaults
                : Defaults extends RegExp
                  ? Destination | Defaults
                  : Defaults extends Promise<any>
                    ? Destination | Defaults
                    : // Ensure we only merge Records
                      Destination extends Input
                      ? Defaults extends Input
                        ? MergeObjects<Destination, Defaults>
                        : Destination | Defaults
                      : Destination | Defaults;

import { describe, test, expect } from "vitest";
import { defu, createDefu } from "../src/defu.ts";

describe("defu regression", () => {
  test("copies missing defaults", () => {
    const result = defu({ a: "c" }, { a: "bbb", d: "c" });
    expect(result).toEqual({ a: "c", d: "c" });
  });

  test("fills null values from defaults", () => {
    const result = defu({ a: null as any }, { a: "c", d: "c" });
    expect(result).toEqual({ a: "c", d: "c" });
  });

  test("merges nested objects", () => {
    const result = defu({ a: { b: "c" } }, { a: { d: "e" } });
    expect(result).toEqual({ a: { b: "c", d: "e" } });
  });

  test("concats arrays by default", () => {
    const result = defu({ array: ["a", "b"] }, { array: ["c", "d"] });
    expect(result).toEqual({ array: ["a", "b", "c", "d"] });
  });

  test("multi defaults", () => {
    const result = defu({ a: 1 }, { b: 2, a: "x" }, { c: 3, a: "x", b: "x" });
    expect(result).toEqual({ a: 1, b: 2, c: 3 });
  });

  test("handles non-object defaults", () => {
    expect(defu({ d: true } as any, null as any)).toEqual({ d: true });
    expect(defu(null as any, { d: true })).toEqual({ d: true });
  });

  test("does not override Object prototype via constructor", () => {
    const payload = JSON.parse('{"constructor": {"prototype": {"isAdmin": true}}}');
    defu({}, payload);
    defu(payload, {});
    defu(payload, payload);
    // @ts-ignore
    expect(({} as any).isAdmin).toBe(undefined);
  });
});

