  "version": "6.1.4",
  "description": "Recursively assign default properties. Lightweight and Fast!",
  "type": "module",
  "license": "MIT",
  "repository": "unjs/defu",
  "main": "src/defu.ts",
  "exports": {
    ".": "./src/defu.ts"
  },
  "scripts": {
    "test": "vitest run",
    "check-types": "tsc --noEmit"
